//! TypeScript for the UI (`mage/web/src/gen/mage.ts`): every [`crate::wire::api`] type, every
//! domain type they embed (collected through `TS::visit_dependencies`), the route templates and
//! the SSE event names. Checked by `generated_ts_is_current`; regenerate with
//! `UPDATE_GENERATED=1 cargo test -p mage-core generated_ts_is_current`.

use std::any::TypeId;
use std::collections::{BTreeMap, HashSet};

use ts_rs::{TS, TypeVisitor};

use crate::domain::RunEvent;
use crate::wire::api::*;

pub const HEADER: &str =
    "// @generated by mage-core tests (UPDATE_GENERATED=1 cargo test -p mage-core generated_ts_is_current). Do not edit.\n\n";

/// Declarations by TypeScript name; sorted output keeps the file stable regardless of the
/// (hash-ordered) dependency visit order ts-rs generates.
#[derive(Default)]
struct Collect {
    seen: HashSet<TypeId>,
    decls: BTreeMap<String, String>,
}

impl TypeVisitor for Collect {
    fn visit<T: TS + 'static + ?Sized>(&mut self) {
        // Primitives and std containers have no declaration; their parameters are visited by
        // the caller's `visit_generics`.
        if T::output_path().is_none() || !self.seen.insert(TypeId::of::<T>()) {
            return;
        }
        self.decls.entry(T::ident()).or_insert_with(|| {
            let mut decl = String::new();
            if let Some(docs) = T::DOCS {
                decl.push_str(docs);
            }
            decl.push_str("export ");
            decl.push_str(T::decl().trim_end());
            if !decl.ends_with(';') {
                decl.push(';');
            }
            decl
        });
        T::visit_dependencies(self);
        T::visit_generics(self);
    }
}

/// The whole generated file.
pub fn typescript() -> String {
    let mut collect = Collect::default();
    macro_rules! roots {
        ($($t:ty),* $(,)?) => { $( collect.visit::<$t>(); )* };
    }
    roots!(
        // common
        ApiErrorCode,
        ApiError,
        ApiErrorBody,
        Paged<TicketSummary>,
        RunStarted,
        JobQueued,
        FeedKind,
        FeedEvent,
        RunEvent,
        // session
        SessionView,
        SessionMembership,
        ResolvedKind,
        ResolvedId,
        CreateOrgRequest,
        // tickets, causes, fix
        TicketListQuery,
        TopCause,
        TicketSummary,
        TicketDetail,
        SetTargetRequest,
        ResolveTicketRequest,
        StartHarnessRunRequest,
        FixBriefQuery,
        FixBriefView,
        // runs
        RunListQuery,
        RunSummary,
        RunDetail,
        RunEventsQuery,
        RunEventPage,
        SteerRequest,
        CommandQueued,
        RunStatusView,
        ArtifactView,
        ArtifactList,
        ShareLink,
        // repos
        VersionView,
        RecipeBrief,
        RepoSummary,
        RepoList,
        RepoDetail,
        InstallationRepo,
        InstallationRepoList,
        ConnectRepoRequest,
        IndexVersionRequest,
        StartLearnRequest,
        RecipeHistory,
        SaveRecipeRequest,
        SavedRecipe,
        VerifyRecipeRequest,
        DeploymentList,
        SetDeploymentRequest,
        CustomerList,
        CustomerInput,
        // settings
        RunBudgets,
        GeneralSettings,
        TriageSettings,
        OrgSettings,
        ModelRouteKind,
        ModelKeyMeta,
        ModelSettingsView,
        ModelSettingsUpdate,
        SetModelKeyRequest,
        IntegrationList,
        ConnectIntegrationResponse,
        // members, audit, usage
        MemberView,
        InviteView,
        MemberList,
        InviteRequest,
        SetRoleRequest,
        AuditActor,
        AuditOutcome,
        AuditQuery,
        AuditDetail,
        AuditEntry,
        AuditPage,
        UsageGroupBy,
        UsageQuery,
        UsageRow,
        UsageReport,
    );

    let mut out = String::from(HEADER);
    for decl in collect.decls.values() {
        // ts-rs 10 renders 64-bit integers as `bigint`; JSON numbers are `number` in the browser
        // (ids, counters and micros stay below 2^53), as aho-cloud's generator configures.
        out.push_str(&decl.replace("bigint", "number"));
        out.push_str("\n\n");
    }
    push_consts(&mut out, "routes", routes::ALL);
    push_consts(&mut out, "sseEvents", sse::ALL);
    out.push_str(
        "/** Fills `{name}` placeholders, URI-encoding each value. */\n\
         export function fill(template: string, args: Record<string, string>): string {\n  \
         return template.replace(/\\{(\\w+)\\}/g, (_, k: string) => encodeURIComponent(args[k] ?? \"\"));\n}\n",
    );
    out
}

fn push_consts(out: &mut String, name: &str, items: &[(&str, &str)]) {
    out.push_str(&format!("export const {name} = {{\n"));
    for (key, value) in items {
        out.push_str(&format!("  {key}: {value:?},\n"));
    }
    out.push_str("} as const;\n\n");
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;
    use std::path::PathBuf;

    use super::*;

    fn generated_path() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../web/src/gen/mage.ts")
    }

    #[test]
    fn generated_ts_is_current() {
        let path = generated_path();
        let want = typescript();
        if std::env::var_os("UPDATE_GENERATED").is_some() {
            if let Some(dir) = path.parent() {
                std::fs::create_dir_all(dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display()));
            }
            std::fs::write(&path, &want).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
            return;
        }
        let have = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(
            have == want,
            "mage/web/src/gen/mage.ts is stale; run `UPDATE_GENERATED=1 cargo test -p mage-core generated_ts_is_current`"
        );
    }

    /// Every capitalized identifier used in a type body is declared in the file (or is a TS
    /// builtin): a domain type reached only through a `#[ts(type)]` override or a missing derive
    /// would otherwise leave a dangling name the UI cannot compile against.
    #[test]
    fn generated_ts_declares_every_type_it_references() {
        let text = typescript();
        let without_comments =
            regex::Regex::new(r"(?s)/\*.*?\*/|//[^\n]*").map(|re| re.replace_all(&text, "").into_owned()).unwrap_or_default();
        let without_strings =
            regex::Regex::new(r#""(?:[^"\\]|\\.)*""#).map(|re| re.replace_all(&without_comments, "\"\"").into_owned()).unwrap_or_default();
        let declared: BTreeSet<&str> = without_strings
            .lines()
            .filter_map(|l| l.strip_prefix("export type "))
            .filter_map(|l| l.split([' ', '<', '=']).next())
            .collect();
        assert!(declared.contains("TicketDetail") && declared.contains("Ticket") && declared.contains("RunId"), "{declared:?}");
        let builtins = ["Array", "Record", "Partial", "T"];
        let ident = regex::Regex::new(r"\b[A-Z][A-Za-z0-9_]*\b").unwrap_or_else(|e| panic!("{e}"));
        let body: String = without_strings.split("export const routes").next().unwrap_or_default().to_owned();
        let undeclared: BTreeSet<&str> =
            ident.find_iter(&body).map(|m| m.as_str()).filter(|n| !declared.contains(n) && !builtins.contains(n)).collect();
        assert!(undeclared.is_empty(), "undeclared TypeScript names: {undeclared:?}");
        assert!(!text.contains("bigint"));
    }
}
